\documentclass[11pt]{article}

\usepackage[margin=1in]{geometry}
\usepackage{amsmath, amssymb, amsthm}
\usepackage{enumitem}
\usepackage{hyperref}

\theoremstyle{plain}
\newtheorem{theorem}{Theorem}[section]
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{proposition}[theorem]{Proposition}
\newtheorem{corollary}[theorem]{Corollary}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}

\newcommand{\CH}{\mathrm{CH}}
\newcommand{\VL}{V{=}L}
\newcommand{\atom}{\mathrm{atom}}
\newcommand{\flip}{\mathrm{flip}}
\newcommand{\eval}{\mathrm{eval}}
\newcommand{\full}{\mathrm{full}}
\newcommand{\true}{\texttt{true}}
\newcommand{\false}{\texttt{false}}
\newcommand{\Meas}{\mathrm{Meas}}

\title{The Combinatorial Core of the Set-Theoretic Multiverse}
\author{Aristotle}
\date{2026-07-13}

\begin{document}
\maketitle

\begin{abstract}
We develop a self-contained, elementary model of the combinatorial heart of the
set-theoretic \emph{multiverse} --- the view that there is no single universe of
sets but a plurality of models of set theory, connected by forcing and
disagreeing on independent statements such as the Continuum Hypothesis. We
abstract a model of set theory to a \emph{world}: a truth assignment to a fixed
collection of atomic set-theoretic assertions. \emph{Sentences} are propositional
combinations of atoms; a \emph{multiverse} is a collection of worlds; and a
sentence is \emph{independent} in a multiverse when it holds in one world and
fails in another. Forcing is modeled by the \emph{flip} operation, which toggles
the truth value of a single atom, and a multiverse is \emph{forcing-closed} when
stable under all flips. Our central theorem states that in any nonempty
forcing-closed multiverse, every atomic sentence is independent --- forcing
settles nothing. We complement this with an absoluteness theorem (the laws of
classical logic are valid across every multiverse), a full analysis of a concrete
three-atom instance modeling $\CH$, $\VL$, and the existence of a measurable
cardinal, and the result that the Continuum Hypothesis remains independent even
after adopting the true implication $(\VL)\Rightarrow\CH$ as a law of the
multiverse. We conclude with the counting fact that the full multiverse over $n$
atoms has exactly $2^n$ worlds, and with a program of extensions toward
first-order signatures, Boolean-valued models, genuine forcing posets, and the
modal logic of forcing.
\end{abstract}

\noindent\textbf{Keywords:} set-theoretic multiverse, Continuum Hypothesis,
forcing, independence, absoluteness, propositional semantics, Boolean-valued
models.

\section{Introduction}

\subsection{Background and motivation}

Two landmark theorems concern the \emph{limits} of what the standard axioms of set
theory (ZFC) can decide. G\"odel (1940) proved that the Continuum Hypothesis
$\CH$ --- the assertion that there is no cardinality strictly between that of the
integers and that of the reals --- is \emph{consistent} with ZFC, by constructing
the constructible universe $L$ in which $\CH$ holds. Cohen (1963) proved the
complementary result that $\lnot\CH$ is also consistent, by inventing
\emph{forcing}, a method for extending a model of ZFC by a generic object that
decides $\CH$ negatively. Together these results show $\CH$ is \emph{independent}
of ZFC: neither it nor its negation is provable.

The classical reading treats independence as an incompleteness. The
\emph{multiverse} perspective, articulated by Hamkins, offers a different
interpretation: there is no privileged universe of sets, but rather a vast
plurality of set-theoretic universes, each a legitimate context for mathematics,
connected to one another by constructions such as forcing. On this view, $\CH$
does not have a hidden true value awaiting discovery; it simply holds in some
universes and fails in others.

\subsection{Contribution}

Our aim is to isolate the \emph{combinatorial core} of the phenomenon of
independence-under-forcing and prove sharp theorems about it from first
principles. We abstract away the internal structure of models of ZFC, retaining
only the \emph{answers} a universe gives to a fixed list of yes/no questions.
This abstraction captures: (1) the absoluteness of logic; (2) the headline
theorem that forcing settles nothing; (3) a concrete instance reproducing the
independence of $\CH$ and $\VL$; and (4) the counting fact that the full
multiverse over $n$ atoms has $2^n$ worlds.

\section{The language of the multiverse}

Fix a type $\alpha$ of \emph{atomic assertions} --- the primitive set-theoretic
yes/no statements we track, e.g.\ $\CH$, $\VL$, ``there is a measurable
cardinal.''

\begin{definition}[Sentence]
The set $\mathrm{Sentence}(\alpha)$ of \emph{sentences over $\alpha$} is generated
inductively: for each atom $a$, $\atom(a)$ is a sentence; $\top$ and $\bot$ are
sentences; if $p$ is a sentence, so is $\lnot p$; and if $p,q$ are sentences, so
are $p\land q$, $p\lor q$, and $p\Rightarrow q$.
\end{definition}

\begin{definition}[World]
A \emph{world} over $\alpha$ is a function $w:\alpha\to\{\true,\false\}$, a truth
assignment to the atoms. It is our abstraction of a model of set theory.
\end{definition}

\begin{definition}[Evaluation]
Each world $w$ extends to $\eval_w:\mathrm{Sentence}(\alpha)\to\{\true,\false\}$
by structural recursion:
\begin{align*}
\eval_w(\atom(a)) &= w(a), & \eval_w(\top) &= \true, & \eval_w(\bot) &= \false,\\
\eval_w(\lnot p) &= \lnot\,\eval_w(p), & \eval_w(p\land q) &= \eval_w(p)\wedge\eval_w(q),\\
\eval_w(p\lor q) &= \eval_w(p)\vee\eval_w(q), & \eval_w(p\Rightarrow q) &= \lnot\,\eval_w(p)\vee\eval_w(q).
\end{align*}
\end{definition}

\begin{definition}[Satisfaction]
A world $w$ \emph{satisfies} a sentence $p$, written $w\models p$, when
$\eval_w(p)=\true$.
\end{definition}

\begin{lemma}[Satisfaction clauses]\label{lem:sat}
For any world $w$ and sentences $p,q$:
$w\models\atom(a)\iff w(a)=\true$; $w\models\top$ always and $w\not\models\bot$;
$w\models\lnot p\iff w\not\models p$; $w\models p\land q\iff (w\models p$ and
$w\models q)$; $w\models p\lor q\iff (w\models p$ or $w\models q)$; and
$w\models p\Rightarrow q\iff (w\models p$ implies $w\models q)$.
\end{lemma}

\begin{proof}
Each clause unfolds $\eval$, the implication clause verified over the four
truth-value combinations of $p$ and $q$.
\end{proof}

\begin{definition}[Multiverse]
A \emph{multiverse} over $\alpha$ is a collection $M$ of worlds.
\end{definition}

\begin{definition}[Valid, refutable, independent, settled]
Fix a multiverse $M$ and a sentence $p$. Then $p$ is \emph{valid} in $M$ if
$w\models p$ for all $w\in M$; \emph{refutable} if $w\not\models p$ for all
$w\in M$; \emph{independent} if there exist $w_1,w_2\in M$ with $w_1\models p$ and
$w_2\not\models p$; and \emph{settled} if valid or refutable.
\end{definition}

\section{The grammar of independence}

\begin{proposition}\label{prop:indep}
Let $p$ be independent in $M$. Then $p$ is not valid, not refutable, and not
settled in $M$.
\end{proposition}

\begin{proof}
A refuting world contradicts validity; a satisfying world contradicts
refutability; settledness is excluded because it is validity or refutability.
\end{proof}

\begin{proposition}
If $p$ is valid in $M$, then $p$ is not independent in $M$.
\end{proposition}

\begin{proof}
Contraposition of Proposition~\ref{prop:indep}.
\end{proof}

\begin{proposition}[Negation symmetry]
$p$ is independent in $M$ iff $\lnot p$ is.
\end{proposition}

\begin{proof}
By Lemma~\ref{lem:sat}, $w\models\lnot p\iff w\not\models p$, so a witnessing
pair for $p$ is a witnessing pair for $\lnot p$ with the roles exchanged, and
conversely.
\end{proof}

\section{Absoluteness: the laws of logic hold everywhere}

\begin{theorem}[Absoluteness of classical logic]\label{thm:abs}
For every multiverse $M$ and every sentence $p$: the excluded middle
$p\lor\lnot p$ is valid; non-contradiction $\lnot(p\land\lnot p)$ is valid; and
self-implication $p\Rightarrow p$ is valid.
\end{theorem}

\begin{proof}
Fix $w\in M$. Since $\eval_w(p)$ is $\true$ or $\false$, in both cases
$\eval_w(p)\vee\lnot\eval_w(p)=\true$, $\lnot(\eval_w(p)\wedge\lnot\eval_w(p))=\true$,
and $\lnot\eval_w(p)\vee\eval_w(p)=\true$. As $w$ was arbitrary, each sentence is
valid.
\end{proof}

The plurality of universes is a plurality of \emph{content}, not of \emph{logic}:
however the branches disagree about $\CH$ or large cardinals, they agree on the
propositional validities.

\section{Forcing as a flip}

Throughout, equality of atoms is decidable.

\begin{definition}[Flip / generic extension]
For a world $w$ and atom $a$, the \emph{flip of $w$ at $a$} is
\[
\flip(w,a)(x)=\begin{cases}\lnot\,w(a), & x=a,\\ w(x), & x\neq a.\end{cases}
\]
It agrees with $w$ off $a$ and negates $w(a)$; it is our abstraction of a
generic extension targeting $a$.
\end{definition}

\begin{lemma}[Flip toggles its target]\label{lem:flip}
For every world $w$ and atom $a$,
$\flip(w,a)\models\atom(a)\iff w\not\models\atom(a)$, and $\flip(w,a)(x)=w(x)$
for $x\neq a$.
\end{lemma}

\begin{proof}
$\flip(w,a)(a)=\lnot w(a)$, so it satisfies $\atom(a)$ iff $w(a)=\false$ iff
$w\not\models\atom(a)$. Agreement off $a$ is by definition.
\end{proof}

\begin{definition}[Forcing-closed multiverse]
A multiverse $M$ is \emph{forcing-closed} if $\flip(w,a)\in M$ for every $w\in M$
and every atom $a$. This abstracts the multiverse axiom that every universe
admits forcing extensions realizing the opposite of any forceable statement.
\end{definition}

\section{The headline theorem: forcing settles nothing}

\begin{theorem}[Forcing settles nothing]\label{thm:head}
Let $M$ be a nonempty forcing-closed multiverse. Then every atomic sentence
$\atom(a)$ is independent in $M$.
\end{theorem}

\begin{proof}
Fix $a$, and choose $w\in M$ (nonempty). Then $\flip(w,a)\in M$
(forcing-closed). By Lemma~\ref{lem:flip}, exactly one of $w$, $\flip(w,a)$
satisfies $\atom(a)$: if $w(a)=\true$ then $w\models\atom(a)$ and
$\flip(w,a)\not\models\atom(a)$; if $w(a)=\false$ the roles reverse. Either way
$M$ contains a satisfying and a refuting world, so $\atom(a)$ is independent.
\end{proof}

\begin{corollary}
In a nonempty forcing-closed multiverse, no atomic sentence is settled.
\end{corollary}

\begin{proof}
Theorem~\ref{thm:head} and Proposition~\ref{prop:indep}.
\end{proof}

\begin{definition}[Full multiverse]
The \emph{full multiverse} $\full(\alpha)$ is the set of all worlds over $\alpha$.
\end{definition}

\begin{proposition}
$\full(\alpha)$ is forcing-closed, and nonempty whenever a world exists; hence
every atomic sentence is independent in it.
\end{proposition}

\begin{proof}
$\flip(w,a)$ is a world, hence already present; the rest is
Theorem~\ref{thm:head}.
\end{proof}

\begin{proposition}[Joint realizability]\label{prop:joint}
For distinct atoms $a\neq b$, the sentence $\atom(a)\land\lnot\,\atom(b)$ is
independent in $\full(\alpha)$.
\end{proposition}

\begin{proof}
The world assigning $\true$ exactly to $a$ satisfies $a\land\lnot b$; the
all-$\false$ world refutes it. Both lie in $\full(\alpha)$.
\end{proof}

\section{A concrete multiverse: $\CH$, $\VL$, and a measurable cardinal}

\begin{definition}
Let the atom-type be $\mathrm{Claim}=\{\CH,\VL,\Meas\}$. Define
\[
\text{G\"odel}:\ \CH\mapsto\true,\ \VL\mapsto\true,\ \Meas\mapsto\false;\qquad
\text{Cohen}:\ \CH\mapsto\false,\ \VL\mapsto\false,\ \Meas\mapsto\false,
\]
and $GC=\{\text{G\"odel},\text{Cohen}\}$. G\"odel models the constructible
universe $L$; Cohen models a Cohen extension violating $\CH$.
\end{definition}

\begin{theorem}[Independence of $\CH$]
$\atom(\CH)$ is independent in $GC$.
\end{theorem}

\begin{proof}
True in G\"odel, false in Cohen.
\end{proof}

\begin{theorem}[Independence of $\VL$]
$\atom(\VL)$ is independent in $GC$.
\end{theorem}

\begin{proof}
True in G\"odel, false in Cohen.
\end{proof}

\begin{theorem}[A law of the multiverse]
$(\VL)\Rightarrow\CH$ is valid in $GC$.
\end{theorem}

\begin{proof}
In G\"odel both sides are true; in Cohen the hypothesis $\VL$ is false, so the
implication holds vacuously.
\end{proof}

Let $\mathrm{LawMV}=\{w:w\models(\VL)\Rightarrow\CH\}$. Both G\"odel and Cohen
belong to $\mathrm{LawMV}$.

\begin{theorem}[$\CH$ stays independent under the law]
$\atom(\CH)$ is independent in $\mathrm{LawMV}$.
\end{theorem}

\begin{proof}
G\"odel and Cohen both obey the law yet disagree on $\CH$.
\end{proof}

\begin{theorem}[A compound with a model]
In $\full(\mathrm{Claim})$, the sentence $\CH\land\lnot(\VL)$ is independent; in
particular it has a model.
\end{theorem}

\begin{proof}
Proposition~\ref{prop:joint} applied to $\CH\neq\VL$.
\end{proof}

\section{Counting worlds}

\begin{theorem}[Cardinality of the full multiverse]
If $\alpha$ is finite with $|\alpha|=n$, then $|\full(\alpha)|=2^{n}$.
\end{theorem}

\begin{proof}
A world is a function $\alpha\to\{\true,\false\}$; there are $2^n$ such.
\end{proof}

\begin{corollary}
Over $\mathrm{Claim}=\{\CH,\VL,\Meas\}$, the full multiverse has exactly $8$
worlds.
\end{corollary}

\section{Discussion}

The model isolates three provable messages. \textbf{A lawful floor:}
Theorem~\ref{thm:abs} guarantees classical logic is absolute, so the multiverse
is a plurality of content, not of logic. \textbf{Generic independence:}
Theorem~\ref{thm:head} shows that once a collection of universes is closed under
forcing, forcing settles no atomic question. \textbf{Structured
(dis)agreement:} branches can share firm laws while remaining divided on the
facts those laws constrain, and independence cannot be legislated away by laws
the branches already obey.

The model is deliberately propositional: worlds are truth assignments, not full
structures, and forcing is abstracted to a single-atom flip. It captures the
combinatorics of independence, with the deep Gödel--Cohen content imported
through the design of the G\"odel and Cohen worlds.

\section{Future directions}

\begin{enumerate}[leftmargin=*]
\item \textbf{Quantified sentences over a signature.} Replace the atom-type by a
first-order language and interpret worlds as structures, recovering the
propositional layer as the atomic-diagram fragment.
\item \textbf{A Boolean/Heyting algebra of multiverse truth values.} Map each
sentence to its set of satisfying worlds; validity, refutability, and
independence become top, bottom, and proper-nontrivial elements. Prove the
assignment is a Boolean homomorphism.
\item \textbf{Forcing posets, not just single flips.} Generalize the flip to a
partial order of finite conditions with genericity and prove a discrete
Rasiowa--Sikorski-style existence lemma.
\item \textbf{Consistency-strength ordering.} Order worlds/theories by
interpretability; prove the settled sentences form a filter closed under modus
ponens.
\item \textbf{Dependence relations.} Formalize when one sentence constrains
another and characterize the settled fragment as the deductive closure of the
shared theory.
\item \textbf{Modal logic of forcing.} Interpret ``forceable'' as a modality and
identify the resulting propositional modal logic (S4.2 for actual forcing).
\end{enumerate}

