        print(f"  {name:32s} -> {status(M, s)}")
    print()


def demo_forcing_settles_nothing() -> None:
    print("=" * 70)
    print("2. Headline theorem: in a nonempty forcing-closed multiverse")
    print("   EVERY atom is independent (forcing settles nothing)")
    print("=" * 70)
