function FORCING_CLOSURE(seeds, atoms):
    seen <- empty set of world-keys
    out, frontier <- [], []
    for s in seeds:
        if key(s) not in seen:
            add key(s) to seen; push s to frontier and out
    while frontier not empty:
        w <- pop(frontier)
        for a in atoms:
            nw <- flip(w, a)
            if key(nw) not in seen:
                add key(nw) to seen; push nw to frontier and out
    return out

